installer-gui-script.script:
function supportedSystem() {
    if (parseInt(system.version.ProductVersion.split('.')[0], 10) < 14) {
        my.result.title = '需要 macOS 14 或更高版本';
        my.result.message = '此试用版适用于 Apple Silicon Mac。';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
